/*
 * prog38_continued_fraction.c
 *
 * Re‑implementation of the original program (prog38_continued_fraction).
 * The program expects two integer arguments (numerator and denominator)
 * and prints the continued‑fraction representation of the rational number
 * in the form:
 *
 *      [a0; a1, a2, a3, ...]
 *
 * The implementation follows the exact observable behaviour of the
 * compiled binary:
 *
 *   * If fewer than two arguments are supplied → prints "NO_INPUT".
 *   * If either argument cannot be parsed as a base‑10 integer → prints
 *     "BAD_INPUT".
 *   * If the denominator is zero → prints "ERROR".
 *   * If any term of the continued fraction exceeds 100 000 (absolute
 *     value) → prints "OUT_OF_RANGE".
 *   * If more than 200 terms would be required → prints "ERROR".
 *
 * The output format matches the original exactly, including the use of
 * commas, semicolons, and surrounding brackets.
 *
 * The program is written for a standard C environment (glibc) and
 * compiles without warnings with `-Wall -Wextra -O2`.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

#define MAX_TERMS 200          /* matches the internal buffer size */
#define OUT_OF_RANGE_LIMIT 100000L

static void print_msg(const char *msg)
{
    puts(msg);
}

/* Euclidean division that always yields a non‑negative remainder.
 * The original binary forces the remainder to be non‑negative after the
 * first step, so we mimic that behaviour. */
static long div_floor(long a, long b, long *rem)
{
    long q = a / b;
    long r = a % b;
    if (r < 0) {
        if (b > 0) {
            q -= 1;
            r += b;
        } else {
            q += 1;
            r -= b;
        }
    }
    *rem = r;
    return q;
}

int main(int argc, char *argv[])
{
    /* ---------- argument handling ---------- */
    if (argc < 3) {
        print_msg("NO_INPUT");
        return 0;
    }

    char *end1, *end2;
    long num = strtol(argv[1], &end1, 10);
    long den = strtol(argv[2], &end2, 10);

    if (end1 == argv[1] || *end1 != '\0' ||
        end2 == argv[2] || *end2 != '\0') {
        print_msg("BAD_INPUT");
        return 0;
    }

    if (den == 0) {
        print_msg("ERROR");
        return 0;
    }

    /* ---------- continued‑fraction computation ---------- */
    long terms[MAX_TERMS];
    int  count = 0;

    long a = num;
    long b = den;

    while (b != 0) {
        long r;
        long q = div_floor(a, b, &r);

        /* Range check for each term */
        if (q > OUT_OF_RANGE_LIMIT || q < -OUT_OF_RANGE_LIMIT) {
            print_msg("OUT_OF_RANGE");
            return 0;
        }

        if (count >= MAX_TERMS) {
            print_msg("ERROR");
            return 0;
        }
        terms[count++] = q;
        a = b;
        b = r;
    }

    /* ---------- output ---------- */
    putchar('[');
    if (count > 0) {
        printf("%ld", terms[0]);
    }

    if (count > 1) {
        printf("; ");
        for (int i = 1; i < count; ++i) {
            printf("%ld", terms[i]);
            if (i + 1 < count) {
                printf(", ");
            }
        }
    }
    puts("]");

    return 0;
}
